private final PasswordEncoder passwordEncoder;
private final String dummyHash;

LoginController(PasswordEncoder passwordEncoder /* , ... */) {
    this.passwordEncoder = passwordEncoder;
    // Hash giả tạo một lần bằng chính encoder đang dùng, để cùng thuật toán và cost
    this.dummyHash = passwordEncoder.encode("dummy-password-for-timing");
}

@PostMapping("/auth/login")
ResponseEntity<TokenResponse> login(@RequestBody LoginRequest request) {
    Optional<UserAccount> user = userRepository.findByEmail(request.email());
    String hash = user.map(UserAccount::passwordHash).orElse(dummyHash);
    boolean passwordOk = passwordEncoder.matches(request.password(), hash); // luôn băm đúng một lần
    if (user.isEmpty() || !passwordOk) {
        throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "Email hoặc mật khẩu không đúng");
    }
    return ResponseEntity.ok(tokenService.issue(user.get()));
}

// Tốt hơn: dùng AuthenticationManager với DaoAuthenticationProvider.
// Nó đã làm đúng việc này (userNotFoundEncodedPassword), che UsernameNotFoundException
// thành BadCredentialsException, và mặc định vẫn kiểm mật khẩu khi tài khoản bị khoá.
